import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Octane and long-running workers","description":"","frontmatter":{},"headers":[],"relativePath":"dev/architecture/octane.md","filePath":"dev/architecture/octane.md"}'),n={name:"dev/architecture/octane.md"};function s(i,e,c,d,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="octane-and-long-running-workers" tabindex="-1">Octane and long-running workers <a class="header-anchor" href="#octane-and-long-running-workers" aria-label="Permalink to &quot;Octane and long-running workers&quot;">​</a></h1><p>The application runs on Laravel Octane. It boots once and then serves many requests in the same process, so state can leak between requests.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li><strong>Never store request-specific state</strong> in singletons or static properties.</li><li>Prefer <strong>scoped bindings</strong> (<code>$this-&gt;app-&gt;scoped()</code>) over singletons for per-request services. Example: <code>ServicePriceDisplay</code> is bound with <code>scoped()</code> in <code>PromotionsServiceProvider</code>.</li><li>Do not inject the request or the authenticated user into a singleton&#39;s constructor.</li><li>Cached values must be keyed by what they depend on (for example the home payload is cached under a versioned key).</li></ul><h2 id="detecting-the-driver" tabindex="-1">Detecting the driver <a class="header-anchor" href="#detecting-the-driver" aria-label="Permalink to &quot;Detecting the driver&quot;">​</a></h2><p>Use <code>config(&#39;octane.server&#39;)</code> if you must write driver-specific code (<code>swoole</code>, <code>roadrunner</code> or <code>frankenphp</code>).</p><h2 id="why-it-matters-here" tabindex="-1">Why it matters here <a class="header-anchor" href="#why-it-matters-here" aria-label="Permalink to &quot;Why it matters here&quot;">​</a></h2><ul><li>Home content and promotions are cached. Writes bump a cache version so the next request sees fresh data. See <a href="./../domain/homepage">Homepage</a> and <a href="./../domain/promotions">Promotions</a>.</li><li>Queue workers are also long-running: restart them after a deployment so they load new code.</li></ul>',8)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
